  if (!a) throw new Error('Choose the equipment this work order is for.');
  if (!String(data.issue || '').trim()) throw new Error('Describe the issue or the work needed.');
  const status = WO_STATUS.includes(data.status) ? data.status : 'Reported';
  const d = { ...(old || {}), ...data, status, site: a.site || '', serial: a.serial || '', updatedAt: stamp(), updatedBy: who() };
  if (status === 'Completed' && !isISO(d.completedDate)) d.completedDate = todayISO();
  if (woOpen(status)) d.completedDate = '';
  if (!isISO(d.reportedDate)) d.reportedDate = todayISO();
  if (!old || old.status !== status) d.history = [...(old?.history || []), { at: stamp(), status, by: who() }];
  if (!old) Object.assign(d, { createdAt: stamp(), createdBy: who(), reportedBy: d.reportedBy || who() });
  delete d.id;
