  const a = store.rows('mheAssets').find(x => assetKey(x) === data.assetId);
  if (!a) throw new Error('Choose the equipment that was inspected.');
  if (!isISO(data.date)) throw new Error('Enter the inspection date.');
  if (!data.result) throw new Error('Choose the result.');
