    exc, openExc, bySite, mix, leases: A.filter(a => ['Active', 'Ending in 90 Days'].includes(a.leaseStatus)), leaseMonthly: A.reduce((t, a) => t + a.leaseMonthly, 0), leaseRemaining: A.reduce((t, a) => t + num(a.leaseRemaining), 0), leaseMissing: A.filter(a => a.leaseStatus === 'Missing Data').length,
