    insp, dailyDue, inspOverdue: dailyDue.filter(a => a.inspStatus === 'Overdue'), inspNone: dailyDue.filter(a => a.inspStatus === 'None on record'), inspCurrent: dailyDue.filter(a => a.inspStatus === 'Current'),
    plannedDue: active.filter(a => a.plannedStatus === 'Overdue' || a.plannedStatus === 'Due soon'), openCA: insp.filter(i => i.caOpen),
